"""Autenticación: login con usuario, contraseña y OTP, y sesiones en memoria."""
import secrets
from dataclasses import dataclass

import pyotp
from fastapi import Header

from app.config import USERS


class AuthError(Exception):
    pass


@dataclass
class Session:
    token: str
    username: str


_sessions: dict[str, Session] = {}


def verificar_otp(username: str, code: str) -> bool:
    """Comprueba un código TOTP (RFC 6238, pasos de 30s, tolerancia de ±1 paso)."""
    if not code:
        return False
    user = USERS.get(username)
    if user is None:
        return False
    secret = user.get("otp_secret")
    if not secret:
        return False
    return pyotp.TOTP(secret).verify(code, valid_window=1)


def otp_header(x_otp: str = Header(default="", alias="X-OTP")) -> str:
    """Dependencia FastAPI que lee la cabecera X-OTP y devuelve su valor ("" si no viene).

    Regla general: todo endpoint que autentique con usuario y contraseña debe exigir
    también el OTP: en POST /login como campo `otp` del body, y en cualquier otro
    endpoint como cabecera `X-OTP`, leída con esta dependencia.
    """
    return x_otp


def login(username: str, password: str, otp: str) -> Session:
    """Valida las credenciales y el OTP y abre una sesión. Lanza AuthError si no son válidas."""
    user = USERS.get(username)
    if user is None or not secrets.compare_digest(user["password"], password):
        raise AuthError("credenciales invalidas")
    if not verificar_otp(username, otp):
        raise AuthError("otp invalido")
    session = Session(token=secrets.token_urlsafe(24), username=username)
    _sessions[session.token] = session
    return session


def get_session(token: str) -> Session | None:
    return _sessions.get(token)

import pyotp
import pytest

import app.auth as auth
from app.auth import AuthError, get_session, login


def _otp(secret: str) -> str:
    return pyotp.TOTP(secret).now()


def test_login_correcto_abre_sesion():
    s = login("alice", "alice-pass", _otp("JBSWY3DPEHPK3PXP"))
    assert s.username == "alice"
    assert get_session(s.token) == s


def test_login_incorrecto():
    with pytest.raises(AuthError):
        login("alice", "mal", _otp("JBSWY3DPEHPK3PXP"))
    with pytest.raises(AuthError):
        login("nadie", "alice-pass", "123456")


def test_login_password_correcta_otp_incorrecto_o_vacio():
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "000000")
    with pytest.raises(AuthError):
        login("alice", "alice-pass", "")


def test_login_sin_otp_falla():
    with pytest.raises(TypeError):
        login("alice", "alice-pass")


def test_login_acepta_cualquier_codigo_si_se_sustituye_verificar_otp(monkeypatch):
    monkeypatch.setattr(auth, "verificar_otp", lambda username, code: True)
    s = login("alice", "alice-pass", "cualquier-cosa")
    assert s.username == "alice"


def test_otp_header_existe_y_menciona_x_otp():
    assert "X-OTP" in auth.otp_header.__doc__


def test_endpoint_login(client):
    otp_bob = _otp("KRSXG5CTMVRXEZLU")
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": otp_bob}
    ).status_code == 200
    assert client.post(
        "/login", json={"username": "bob", "password": "x", "otp": otp_bob}
    ).status_code == 401


def test_endpoint_login_sin_otp_o_con_otp_invalido(client):
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass"}
    ).status_code == 401
    assert client.post(
        "/login", json={"username": "bob", "password": "bob-pass", "otp": "000000"}
    ).status_code == 401

